<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><div class="dv-content"><h1>Saisie de données client</h1><?php if(session('error')): ?><p class="dv-alert dv-alert-danger"><?= esc(session('error')) ?></p><?php endif ?><form method="post" action="<?= site_url('saisie/client') ?>" class="dv-card"><?= csrf_field() ?><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px"><?php foreach(['identifiant'=>'Identifiant','Nom'=>'Nom *','Prenom'=>'Prénom *','age'=>'Âge *','adresse'=>'Résidence *'] as $name=>$label): ?><div class="dv-form-group"><label class="dv-label"><?= $label ?></label><input class="dv-input" name="<?= $name ?>" value="<?= esc(old($name)) ?>" <?= $name==='age'?'type="number" min="0" max="150"':'' ?>></div><?php endforeach ?><div class="dv-form-group"><label class="dv-label">Région *</label><select class="dv-select" id="region" name="region" required><option value="">Sélectionner une région</option></select></div><div class="dv-form-group"><label class="dv-label">District *</label><select class="dv-select" id="district" name="district" required><option value="">Sélectionner d’abord une région</option></select></div><div class="dv-form-group"><label class="dv-label">Genre *</label><select class="dv-select" name="genre" required><option value="">Sélectionner</option><option>Masculin</option><option>Feminin</option><option>Inconnue</option></select></div><div class="dv-form-group"><label class="dv-label">Type *</label><select class="dv-select" name="type_client" required><option value="">Sélectionner</option><option>Ambulatoire</option><option>Hospitalisé</option></select></div></div><button class="dv-btn dv-btn-primary">Enregistrer</button></form></div><script>const geo={Analamanga:['Ambohidratrimo','Andramasina','Anjozorobe','Ankazobe','Antananarivo Atsimondrano','Antananarivo Avaradrano','Antananarivo Renivohitra','Manjakandriana'],Vakinankaratra:['Ambatolampy','Antanifotsy','Antsirabe I','Antsirabe II',